SELECT Phone FROM schools WHERE CDSCode IN (
    SELECT CDSCode FROM frpm WHERE "Charter School (Y/N)" = 1
) AND OpenDate > '2000-01-01' AND FundingType = 'Direct'

SELECT 
    (SELECT COUNT(*) FROM schools WHERE County = 'Orange' AND DOC = '54') * 1.0 /
    (SELECT COUNT(*) FROM schools WHERE County = 'Orange' AND DOC = '52') AS unified_to_elementary_ratio;

SELECT MIN(amount)
FROM loan
WHERE status = 'A' AND strftime('%Y', date) = '1997';

SELECT district_id, A11
FROM district
WHERE A11 > 8000 AND A11 <= 9000;

WITH coldsnap_code AS (
    SELECT code FROM sets WHERE name = 'Coldsnap'
),
coldsnap_cards AS (
    SELECT * FROM cards WHERE setCode = (SELECT code FROM coldsnap_code)
)
SELECT 
    100.0 * COUNT(CASE WHEN cardKingdomFoilId IS NOT NULL AND cardKingdomId IS NOT NULL THEN 1 END) / COUNT(*) AS percentage_incredibly_powerful
FROM coldsnap_cards;

SELECT COUNT(*) FROM cards WHERE rarity = 'rare' AND types = 'Enchantment' AND name = 'Abundance' AND NOT EXISTS (
    SELECT 1 FROM legalities l WHERE l.uuid = cards.uuid AND l.status != 'Legal'
)

SELECT
    ABS(
        (SELECT COUNT(*) FROM superhero s JOIN publisher p ON s.publisher_id = p.id WHERE p.publisher_name = 'DC Comics')
        -
        (SELECT COUNT(*) FROM superhero s JOIN publisher p ON s.publisher_id = p.id WHERE p.publisher_name = 'Marvel Comics')
    ) AS difference;

