WITH race_info AS (
  SELECT raceId FROM races WHERE date = '1983-07-16'
),
participants AS (
  SELECT driverId FROM results WHERE raceId = (SELECT raceId FROM race_info)
),
completions AS (
  SELECT driverId FROM results WHERE raceId = (SELECT raceId FROM race_info) AND time IS NOT NULL
)
SELECT 
  (SELECT COUNT(*) FROM completions) * 1.0 / (SELECT COUNT(*) FROM participants) AS completion_rate_percentage
;

WITH race AS (
  SELECT raceId FROM races WHERE year = 2008 AND name = 'Australian Grand Prix'
),
total_drivers AS (
  SELECT COUNT(DISTINCT driverId) AS total FROM results WHERE raceId = (SELECT raceId FROM race)
),
completed_drivers AS (
  SELECT COUNT(*) AS completed FROM results WHERE raceId = (SELECT raceId FROM race) AND time IS NOT NULL
)
SELECT 
  CAST(completed_drivers.completed AS REAL) / total_drivers.total AS completion_rate
FROM completed_drivers, total_drivers;

